pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint256).max / 2);
        Reverter actor = new Reverter();
        vm.deal(address(actor), amount);
        actor.doDeposit(c, amount);
        // In P, withdrawAll reverts because the external call to the actor fails.
        // In M, the require is deleted, so it completes without reverting.
        bool ok = actor.tryWithdraw(c);
        assertTrue(ok, "withdrawAll should revert on failed external call");
    }
}

contract Reverter {
    fallback() external payable { revert(); }

    function doDeposit(C c, uint256 amount) external payable {
        c.deposit{value: amount}();
    }

    function tryWithdraw(C c) external returns (bool) {
        try c.withdrawAll() { return true; } catch { return false; }
    }
}

