pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    FailingActor a;

    function setUp() public { c = new C(); a = new FailingActor(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e30);
        vm.deal(address(a), amount);
        a.deposit(address(c), amount);
        uint256 before = address(a).balance;
        bool ok;
        try a.withdrawAll(address(c)) { ok = true; } catch { ok = false; }
        // Rule: any non-reverting withdrawAll must actually have paid out the credit.
        assertTrue(!ok || address(a).balance > before);
    }
}

contract FailingActor {
    function deposit(address target, uint256 amt) external payable {
        require(msg.value == amt);
        C(target).deposit{value: amt}();
    }
    function withdrawAll(address target) external {
        C(target).withdrawAll();
    }
    fallback() external payable { revert(); }
}

