pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    RevWallet h;

    function setUp() public {
        c = new C();
        h = new RevWallet(c);
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 2 ** 96);
        vm.deal(address(h), amount);
        h.depositTo(amount);
        // Caller's wallet rejects ETH, so the payout transfer inside withdrawAll fails.
        h.pull();
        // Reference: the failed transfer reverts the whole withdrawal, so the credit is intact.
        // Mutant: require is deleted, withdrawal completes and the credit is destroyed.
        assertTrue(c.credit(address(h)) == amount);
    }
}

contract RevWallet {
    C c;
    constructor(C _c) { c = _c; }
    function depositTo(uint256 a) external { c.deposit{value: a}(); }
    function pull() external { c.withdrawAll(); }
    receive() external payable { revert(); }
}

