pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        vm.assume(actor.code.length == 0);
        amount = bound(amount, 1, type(uint256).max / 2);

        // adversarial counterparty: always rejects incoming value
        Reverter h = new Reverter();

        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();
        assertEq(address(c).balance, amount);

        // the credit is withdrawable only to the rejecting helper
        vm.prank(actor);
        (bool ok, ) = address(h).call(abi.encodeWithSignature("withdraw(address)", c));
        assertTrue(ok); // helper successfully drove c.withdrawAll via re-entry route below

        // drive c.withdrawAll from the helper's address with the failing receiver
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();
        uint256 before = address(c).balance;

        vm.prank(address(h));
        bool withdrew;
        try this.callWithdraw(c) {
            withdrew = true;
        } catch {
            withdrew = false;
        }

        // GENERAL RULE: if withdrawAll completes without reverting,
        // c's balance must decrease by the full credit it paid out.
        assertTrue(!withdrew || address(c).balance == before - amount);
    }

    function callWithdraw(C target) external {
        target.withdrawAll();
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }

    function withdraw(address payable target) external {
        (bool s, ) = target.call(abi.encodeWithSignature("withdrawAll()"));
        require(s);
    }
}

