pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, bool failMode) public {
        amount = bound(amount, 1, 1e30);
        FallbackActor actor = new FallbackActor(failMode);
        vm.deal(address(actor), amount);
        actor.deposit{value: amount}(c);
        bool ok = actor.withdraw(c);
        // Rule: a completed withdrawal pays out ALL of c's ether.
        assertTrue(!ok || address(c).balance == 0);
    }
}

contract FallbackActor {
    bool immutable fail;
    constructor(bool f) { fail = f; }
    fallback() external payable { if (fail) revert(); }
    function deposit(C c) external payable { c.deposit{value: msg.value}(); }
    function withdraw(C c) external returns (bool) {
        try c.withdrawAll() { return true; } catch { return false; }
    }
}

