pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // keep the fuzzed amount admissible: nonzero, payable by the helper
        amount = bound(amount, 1, type(uint128).max);

        // adversarial counterparty: a re-entrant attacker that deposits, then
        // withdraws, and re-enters c from its receive() during the payout call
        Attacker attacker = new Attacker(c);

        vm.deal(address(attacker), amount);
        attacker.doDeposit(amount);

        // drive c through `withdrawAll` via the adversarial counterparty
        attacker.doWithdrawAll();

        // General rule: withdrawing all credited funds pays out exactly the
        // credited amount exactly once, and the contract retains no uncredited
        // ether (real balance consistent with the ledger after the full flow).
        assertTrue(
            attacker.received() == amount && address(c).balance == 0,
            "payout/ledger conservation violated"
        );
    }
}

contract Attacker {
    C public c;
    uint256 public received;
    bool public reenter = true;

    constructor(C _c) { c = _c; }

    function doDeposit(uint256 amt) external payable {
        c.deposit{value: amt}();
    }

    function doWithdrawAll() external {
        reenter = true;
        c.withdrawAll();
    }

    receive() external payable {
        received += msg.value;
        if (reenter) {
            reenter = false;
            // re-enter: observe subsequent operations against the ledger state
            c.withdrawAll();
        }
    }
}
